<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class SupportTicket extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['user_id','merchant_id','created_by','assigned_to','ticket_reference','category','subject','priority','status','resolution_summary','first_response_at','resolved_at','closed_at','sla_due_at','metadata']; protected $casts=['first_response_at'=>'datetime','resolved_at'=>'datetime','closed_at'=>'datetime','sla_due_at'=>'datetime','metadata'=>'array']; public function user(): BelongsTo { return $this->belongsTo(User::class); } public function merchant(): BelongsTo { return $this->belongsTo(Merchant::class); } public function messages(): HasMany { return $this->hasMany(SupportMessage::class); } public function events(): HasMany { return $this->hasMany(SupportTicketEvent::class); } public function attachments(): HasMany { return $this->hasMany(SupportAttachment::class); } }
